#!/usr/bin/env python3
"""Structural validation of a campaign result against PROTOCOL.md v3."""
import base64, ipaddress, plistlib, struct

ADDRESS_KEYS = ('conflicts', 'internal', 'external', 'unresolved')
SERVICE_KEYS = {'id', 'internal_open', 'internal_closed', 'external_open',
                'external_closed', 'internal_only', 'protocol_errors'}
LEASE_KEYS = {'lease', 'state', 'conflicts', 'internal', 'external', 'unresolved',
              'services'}
PLAN_KEYS = {'request', 'offer', 'send', 'finish'}


def fail(where, message):
    raise AssertionError('%s: %s' % (where, message))


def check_addresses(where, values):
    if not isinstance(values, list):
        fail(where, 'list required')
    previous = -1
    for item in values:
        if not isinstance(item, str):
            fail(where, 'string required')
        value = int(ipaddress.IPv6Address(item))
        if item != str(ipaddress.IPv6Address(item)):
            fail(where, 'not compressed lowercase: ' + item)
        if value <= previous:
            fail(where, 'not numerically increasing')
        previous = value


def check_result(job, out):
    if set(out) != {'manifest', 'rejected', 'snapshots', 'active_requests', 'plan'}:
        fail('root', 'keys %s' % sorted(out))
    leases = [l['id'] for l in job['leases']]
    services = [s['id'] for s in job['services']]
    previous = None
    for index, row in enumerate(out['manifest']):
        where = 'manifest[%d]' % index
        if set(row) != {'lease', 'probe', 'target'}:
            fail(where, 'keys')
        if row['lease'] not in leases:
            fail(where, 'unknown lease')
        check_addresses(where, [row['target']])
        subnet, _, slot = row['probe'].partition('/')
        if not subnet.isdigit() or not slot or slot[0] not in 'ci':
            fail(where, 'probe form')
        key = (row['lease'], int(subnet), 0 if slot == 'c' else int(slot[1:]))
        if slot[1:] and not slot[1:].isdigit():
            fail(where, 'slot form')
        if previous is not None and key <= previous:
            fail(where, 'order')
        previous = key
    seen = None
    for index, row in enumerate(out['rejected']):
        if not (isinstance(row, list) and len(row) == 2
                and all(type(x) is int for x in row)):
            fail('rejected[%d]' % index, 'pair required')
        if seen is not None and tuple(row) <= seen:
            fail('rejected[%d]' % index, 'order')
        seen = tuple(row)
    moments = []
    for snap in out['snapshots']:
        if set(snap) != {'at', 'ledger', 'unbound_applications', 'leases'}:
            fail('snapshot', 'keys')
        moments.append(snap['at'])
        if set(snap['ledger']) != {'live', 'deleted', 'conflict'}:
            fail('ledger', 'keys')
        for key, value in snap['ledger'].items():
            if type(value) is not int:
                fail('ledger', key + ' must be an integer')
        if type(snap['unbound_applications']) is not int:
            fail('snapshot', 'unbound must be an integer')
        found = []
        for lease in snap['leases']:
            if set(lease) != LEASE_KEYS:
                fail('lease', 'keys')
            found.append(lease['lease'])
            if lease['state'] not in ('inactive', 'alias', 'conflict', 'usable'):
                fail('lease', 'state')
            for key in ADDRESS_KEYS:
                check_addresses('lease.' + key, lease[key])
            if lease['state'] == 'inactive' and (lease['internal'] or lease['external']
                                                 or lease['conflicts'] or lease['unresolved']):
                fail('lease', 'inactive must be empty')
            if lease['state'] in ('alias', 'conflict') and (lease['internal']
                                                            or lease['external']):
                fail('lease', 'quarantined must have clean roles empty')
            got = []
            for entry in lease['services']:
                if set(entry) != SERVICE_KEYS:
                    fail('service', 'keys')
                got.append(entry['id'])
                for key in ('internal_open', 'internal_closed', 'external_open',
                            'external_closed', 'internal_only'):
                    check_addresses('service.' + key, entry[key])
                if type(entry['protocol_errors']) is not int:
                    fail('service', 'protocol_errors')
                if entry['internal_only'] and entry['internal_only'] != entry['internal_open']:
                    fail('service', 'internal_only must equal internal_open or be empty')
            if got != sorted(services):
                fail('lease', 'services order/completeness')
        if found != sorted(leases):
            fail('snapshot', 'leases order/completeness')
    if moments != sorted(set(job['queries'])):
        fail('snapshots', 'query order')
    names = [row['id'] for row in out['active_requests']]
    if names != sorted(row['id'] for row in job['requests']):
        fail('active_requests', 'ids/order')
    for row in out['active_requests']:
        if set(row) != {'id', 'active'} or not isinstance(row['active'], bool):
            fail('active_requests', 'shape')
    plan = out['plan']
    if set(plan) != {'resolved', 'cost', 'assignments'}:
        fail('plan', 'keys')
    if type(plan['resolved']) is not int or type(plan['cost']) is not int:
        fail('plan', 'counts')
    if plan['resolved'] != len(plan['assignments']):
        fail('plan', 'resolved must count assignments')
    index_by_request = {row['id']: row for row in job['requests']}
    index_by_offer = {row['id']: row for row in job['offers']}
    kinds = {row['id']: row['kind'] for row in job['services']}
    used = set()
    cost = 0
    for entry in plan['assignments']:
        if set(entry) != PLAN_KEYS:
            fail('assignment', 'keys')
        if entry['request'] in used:
            fail('assignment', 'request repeated')
        used.add(entry['request'])
        request = index_by_request[entry['request']]
        offer = index_by_offer[entry['offer']]
        cost += offer['cost']
        check_certificate(entry, kinds[request['service']])
    if [row['request'] for row in plan['assignments']] != sorted(used):
        fail('plan', 'assignments must be sorted by request id')
    if cost != plan['cost']:
        fail('plan', 'cost mismatch')


def decode(where, text):
    try:
        return base64.b64decode(text.encode('ascii'), validate=True)
    except Exception:
        fail(where, 'invalid base64')


def check_certificate(entry, kind):
    where = 'assignment ' + entry['request']
    send = [decode(where + '.send', x) for x in entry['send']]
    finish = [decode(where + '.finish', x) for x in entry['finish']]
    if kind == 'tcp':
        if send or finish:
            fail(where, 'TCP must be empty')
        return
    if kind == 'adb':
        if len(send) != 1 or len(finish) != 1:
            fail(where, 'ADB needs exactly one send and one finish packet')
        command, arg0, arg1, length, check, magic = struct.unpack('<6I', send[0][:24])
        if (command != 0x4e584e43 or magic != (command ^ 0xffffffff) or arg0 != 0x01000000
                or arg1 != 4096 or send[0][24:] != b'host::zgrab2'
                or length != 12 or check != sum(b'host::zgrab2') % (1 << 32)
                or len(send[0]) != 36):
            fail(where, 'bad ADB CNXN')
        command, arg0, arg1, length, check, magic = struct.unpack('<6I', finish[0][:24])
        if (command != 0x45534c43 or magic != (command ^ 0xffffffff) or arg0 or arg1
                or length or check or len(finish[0]) != 24):
            fail(where, 'bad ADB CLSE')
        return
    if finish:
        fail(where, 'sync finish must be empty')
    if len(send) != 2:
        fail(where, 'sync needs two frames')
    for index, frame in enumerate(send):
        want = ('ProductVersion', 'ProductName')[index]
        size = struct.unpack('>I', frame[:4])[0]
        if size != len(frame) - 4 or not 1 <= size <= 65532:
            fail(where, 'bad frame length')
        value = plistlib.loads(frame[4:])
        if (not isinstance(value, dict) or set(value) != {'Key', 'Label', 'ProtocolVersion',
                                                          'Request'}
                or value['Key'] != want or value['Label'] != 'usbmuxd'
                or value['ProtocolVersion'] != '2' or value['Request'] != 'GetValue'
                or not all(isinstance(x, str) for x in value.values())):
            fail(where, 'bad sync request plist')
